bruteForceSolution.code:
function patternInvertedNumberTriangle(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 1; j <= n - i; j++) {
      row += j;
    }
    rows.push(row);
  }
  return rows.join('\n');
}

