function patternInvertedNumberTriangle(n) {
  let full = '';
  for (let i = 1; i <= n; i++) full += i;
  let rows = [];
  for (let i = 0; i < n; i++) {
    rows.push(full.slice(0, n - i));
  }
  return rows.join('\n');
}
